def solve(L_km=13.0, H_km=1.5, u=4.0, b=10.0, q_g=4.5e-6) -> dict:
    # Unit conversions
    L = L_km * 1000.0    # km to m
    H = H_km * 1000.0    # km to m
    q_ug = q_g * 1e6     # g/(s·m^2) to μg/(s·m^2)

    # Fixed box model formula: c = b + (q * L) / (u * H)
    # The second term calculates the concentration added by the city's emissions
    c = b + (q_ug * L) / (u * H)

    return {
        "1": {"value": c, "unit": "μg/m^3"}
    }

