def solve(P=70.0, T_C=10.0, P_o=100.0, R_cp=0.28571) -> dict:
    import math

    # Convert temperature to Kelvin
    T_K = T_C + 273.15

    # Calculate potential temperature in Kelvin using Poisson's equation
    Theta_K = T_K * math.pow(P_o / P, R_cp)

    # Convert potential temperature back to Celsius
    Theta_C = Theta_K - 273.15

    return {
        "1": {"value": Theta_C, "unit": "°C"}
    }

