    z_i = z_i_km * 1000.0  # km to m

    # Deardorff velocity formula: w_* = [ (g / T_v) * z_i * F_H ]^(1/3)
    # It represents the convective velocity scale in the boundary layer.
    w_star = ((g / T_v) * z_i * F_H) ** (1.0 / 3.0)

    return {
        "1": {"value": w_star, "unit": "m s^-1"}
    }

def solve(dz_km=0.5, dq=500.0) -> dict:
    # Convert height change to meters
    Cp = 1004.0  # physical constant (frozen, not an input)
    g = 9.8  # physical constant (frozen, not an input)
    dz = dz_km * 1000.0

    # First Law of Thermodynamics for an air parcel: dq = Cp * dT + g * dz
    # Rearranging to solve for temperature change (dT)
    dT = (dq - g * dz) / Cp

    # A change in Kelvin is equivalent to a change in Celsius
    return {
        "1": {"value": round(dT, 2), "unit": "°C"}
    }

