def solve(dFx=1.0, dFy=2.0, dFz=3.0, dx=1000.0, dy=1000.0, dz=1000.0) -> dict:
    # Given kinematic flux divergence values in K m s^-1
    # Grid spacing in meters (1 km = 1000 m)

    # Calculate the rate of temperature change in K/s (or °C/s)
    # Formula: dT/dt = - (dFx/dx + dFy/dy + dFz/dz)
    dT_dt_s = - (dFx / dx + dFy / dy + dFz / dz)

    # Convert from °C/s to °C/h (1 hour = 3600 seconds)
    dT_dt_h = dT_dt_s * 3600.0

    return {
        "1": {"value": dT_dt_h, "unit": "°C/h"}
    }

