def solve(T=25.0, T_d=18.0, Gamma_s=4.42, Gamma_d=9.8) -> dict:
    # Calculate the height of the Lifting Condensation Level (LCL)
    z_LCL = 0.125 * (T - T_d)

    # Calculate the temperature at the LCL
    T_LCL = T - Gamma_d * z_LCL

    # Calculate the wet-bulb temperature using Normand's Rule
    T_w = T_LCL + Gamma_s * z_LCL

    return {
        "1": {"value": round(T_w, 1), "unit": "°C"}
    }

def solve(z_i=1500.0, bH_wB=0.03, abs_delta_s_theta=7.0, abs_delta_zi_theta=4.0, abs_delta_s_rT=6.0, delta_zi_rT=-3.0) -> dict:
    # (a) Calculate the turbulent flux divergence of r_T
    # Formula: dF/dz = - (bH_wB / z_i) * [0.2 * delta_zi_rT * |delta_s_theta / delta_zi_theta| + |delta_s_rT|]
    term_in_brackets = 0.2 * delta_zi_rT * (abs_delta_s_theta / abs_delta_zi_theta) + abs_delta_s_rT
    flux_div = - (bH_wB / z_i) * term_in_brackets

    # (b) Calculate the rate of total water increase in the ML
    # Formula: dr_T/dt = - dF/dz
    rate_per_second = -flux_div
    rate_per_hour = rate_per_second * 3600.0  # Convert from per second to per hour

    return {
        "a": {"value": flux_div, "unit": "(g kg^{-1})/s"},
        "b": {"value": rate_per_hour, "unit": "(g kg^{-1})/hour"}
    }

