    # B_lambda(T) = (c_{1B} * lambda^{-5}) / (exp(c_2 / (lambda * T)) - 1)
    radiance = (c1B * lam**-5) / (math.exp(c2 / (lam * T_k)) - 1)

    return {
        "1": {"value": round(radiance, 2), "unit": "W * m^-2 * mu m^-1 * sr^-1"}
    }

def solve(L_lambda=1.1, lambda_=6.7, c1B=1.191e8, c2=1.44e4) -> dict:
