    # Brightness temperature formula: T_B = (c2 / lambda) / ln(1 + (c1B * lambda^-5) / L_lambda)
    numerator = c2 / lambda_
    denominator = math.log(1 + (c1B * (lambda_ ** -5)) / L_lambda)
    T_B = numerator / denominator

    return {
