def solve(U=15.0, z_i_km=1.5, C_D=2e-2, w_B=50.0, b_D=1.83e-3) -> dict:
    # Given parameters
    z_i = z_i_km * 1000.0      # ABL depth in m (converted from 1.5 km)

    # (a) Statically neutral ABL over a rough forest
    # Bulk drag force per unit mass for neutral ABL: F = - C_D * U^2 / z_i
    F_a = - C_D * (U ** 2) / z_i

    # (b) Statically unstable ABL having convection
    # Bulk drag force per unit mass for unstable ABL: F = - b_D * w_B * U / z_i
    F_b = - b_D * w_B * U / z_i

    return {
        "a": {"value": F_a, "unit": "m s^-2"},
        "b": {"value": F_b, "unit": "m s^-2"}
    }

def solve(lat_deg=20.0, v=50.0, r=50000.0, dz=15000.0) -> dict:
    two_omega = 1.458e-4  # physical constant (frozen, not an input)
    import math

    # Calculate Coriolis parameter: fc = 2*Omega * sin(latitude)
    lat_rad = math.radians(lat_deg)
    fc = two_omega * math.sin(lat_rad)

    # Calculate relative vorticity for solid-body rotation: zeta_r = 2 * (v / r)
    zeta_r = 2 * (v / r)

    # Calculate potential vorticity: zeta_p = (zeta_r + fc) / dz
    zeta_p = (zeta_r + fc) / dz

    return {
        "1": {"value": zeta_p, "unit": "m^-1 s^-1"}
    }

def solve(zeta_a=1.5e-4, rho=0.7, dtheta_dz_K_per_km=4):
    """
    Compute isentropic potential vorticity (IPV) in PVU.

    Parameters:
    -----------
    zeta_a : float
        Absolute vorticity in s^{-1}
    rho : float
        Air density in kg m^{-3}
    dtheta_dz_K_per_km : float
        Static stability in K km^{-1}

    Returns:
    --------
    dict with IPV in PVU
    """
    # Convert static stability from K/km to K/m
    dtheta_dz = dtheta_dz_K_per_km * 1e-3  # K/km -> K/m (1 km = 1000 m)

    # Compute IPV using the formula: IPV = (zeta_a / rho) * (dtheta/dz)
    # Units: (s^{-1}) / (kg m^{-3}) * (K m^{-1}) = K m^2 s^{-1} kg^{-1}
    IPV_SI = (zeta_a / rho) * dtheta_dz  # in K m^2 s^{-1} kg^{-1}

    # Convert to PVU: 1 PVU = 10^{-6} K m^2 s^{-1} kg^{-1}
    IPV_PVU = IPV_SI / 1e-6

    return {"answer": {"value": IPV_PVU, "unit": "PVU"}}

def solve(lambda_km=8000, A_km=1200, Phi_deg=50, U_o=40, Delta_t_h=12):
    import math

    # Physical constants
    # Given: 2*Omega/R_earth = 2.29e-11 m^{-1} s^{-1}
    two_omega_over_R = 2.29e-11  # m^{-1} s^{-1}

    # Convert inputs to SI units
    lambda_m = lambda_km * 1000.0  # km to m
    A_m = A_km * 1000.0  # km to m
    Phi_rad = math.radians(Phi_deg)  # degrees to radians
    Delta_t_s = Delta_t_h * 3600.0  # hours to seconds

    # Calculate beta parameter
    beta = two_omega_over_R * math.cos(Phi_rad)  # m^{-1} s^{-1}

    # Calculate intrinsic phase speed
    c_o = -beta * (lambda_m / (2 * math.pi))**2  # m s^{-1}

    # Calculate total phase speed
    c = U_o + c_o  # m s^{-1}

    # Calculate wave translation distance
    D_m = c * Delta_t_s  # m
    D_km = D_m / 1000.0  # convert to km

    return {
        "beta": {"value": beta, "unit": "m^{-1} s^{-1}"},
        "c_o": {"value": c_o, "unit": "m s^{-1}"},
        "c": {"value": c, "unit": "m s^{-1}"},
        "D": {"value": D_km, "unit": "km"}
    }

