    radius_m = radius_km * 1000.0
    omega = tangential_speed / radius_m
    return {"1": {"value": 2.0 * omega, "unit": "s^{-1}"}}

def solve(theta_ml=-20.0, z_i=500.0, theta_sfc=0.0, C_H=0.01) -> dict:
