    z_i_km = z_i / 1000.0  # km

    # Calculate the initial rate of temperature change with distance
    # Formula: dTheta_ML / dx = C_H * (Theta_sfc - Theta_ML) / z_i
    rate = (C_H * (theta_sfc - theta_ml)) / z_i_km

    return {
        "1": {"value": rate, "unit": "°C km^{-1}}"}
    }

def solve(P_kPa=103, A=1.0) -> dict:
    # Convert pressure to Pascals (N/m^2)
    g = 9.81  # physical constant (frozen, not an input)
    P_Pa = P_kPa * 1000

    # Pressure is the weight of the air column per unit area: P = (m * g) / A
    # Therefore, mass m = (P * A) / g
    m = (P_Pa * A) / g

    return {
        "1": {"value": round(m, 1), "unit": "kg"}
    }

def solve(delta_P=0.5, R=175, lat=35, rho=1.0) -> dict:
    omega = 7.2921e-5  # physical constant (frozen, not an input)
    import math

    # Given parameters
    delta_P = delta_P * 1000  # Pressure difference magnitude (kPa -> Pa)
    R = R * 1000              # Radius of meso-low (km -> m)

    # Coriolis parameter (f = 2 * Omega * sin(latitude))
    f = 2 * omega * math.sin(math.radians(lat))

    # Geostrophic wind speed (U_g = (1 / (rho * f)) * (delta_P / R))
    U_g = delta_P / (rho * f * R)

    return {
        "1": {"value": round(U_g, 1), "unit": "m s^{-1}"}
    }

def solve(delta_U=15.0, delta_z=3000.0, delta_W=10.0, delta_y=10000.0) -> dict:
    # Calculate gradients
    dU_dz = delta_U / delta_z  # s^-1
    dW_dy = delta_W / delta_y  # s^-1

    # Calculate vorticity spin-up using the simplified vorticity-tendency equation
    # d(zeta_r)/dt = (dU'/dz) * (dW/dy)
    vorticity_spin_up = dU_dz * dW_dy

    return {
        "1": {"value": vorticity_spin_up, "unit": "s^{-2}"}
    }

def solve(M_o=5.0, alpha=2.0, M_min=5.5, M_max=6.5) -> dict:
    import math

    # Center of the wind speed bin (M) and bin width (delta M)
    M = (M_min + M_max) / 2.0
    delta_M = M_max - M_min

    # Approximate probability equation
    # Pr = (alpha * delta_M * M**(alpha - 1) / M_o**alpha) * exp(-(M / M_o)**alpha)
    Pr = (alpha * delta_M * (M ** (alpha - 1)) / (M_o ** alpha)) * math.exp(-((M / M_o) ** alpha))

    # Convert probability to percentage
    Pr_percent = Pr * 100

    return {
        "1": {"value": Pr_percent, "unit": "%"}
    }

