def solve(R=30.0, M_in=10.0, E=0.40, rho=1.225) -> dict:
    # Calculate theoretical power output in Watts
    # Formula: Power = (pi / 2) * rho * E * R^2 * M_in^3
    power_W = (math.pi / 2) * rho * E * (R ** 2) * (M_in ** 3)

    # Convert Watts to Kilowatts
    power_kW = power_W / 1000.0

    return {
        "1": {"value": round(power_kW), "unit": "kW"}
    }

def solve(alpha_deg=10, delta_theta_v=10, h=20, T_ve=283, C_D=0.005) -> dict:
    g = 9.8  # physical constant (frozen, not an input)
    import math

    # Convert slope angle to radians
    alpha_rad = math.radians(alpha_deg)

    # Calculate equilibrium speed of the katabatic wind
    # Formula: |U_eq| = [ | g * (delta_theta_v / T_ve) * (h / C_D) * sin(alpha) | ]^(1/2)
    U_eq_sq = g * (delta_theta_v / T_ve) * (h / C_D) * math.sin(alpha_rad)
    U_eq = math.sqrt(abs(U_eq_sq))

    return {
        "1": {"value": round(U_eq, 1), "unit": "m s^{-1}"}
    }

def solve(F_H=0.2, M=5, gamma_km=3, x_km=5) -> dict:
    import math

    # Convert to SI units (meters, seconds, Kelvin)
    gamma = gamma_km / 1000.0  # K/m
    x = x_km * 1000.0          # m

    # Calculate TIBL depth zi in meters
    # Formula: z_i = [ (2 * F_H / (gamma * M)) * x ]^(1/2)
    zi_m = math.sqrt((2 * F_H / (gamma * M)) * x)

    # Convert back to km for the final answer
    zi_km = zi_m / 1000.0

    return {
