    g_prime = g_over_Tv * delta_T

    # Using Bernoulli's equation along the top streamline where P is constant:
    # 0.5 * u1^2 + g_prime * z1 = 0.5 * u2^2 + g_prime * z2
    # Assuming initial height z1 = 0
    z2 = (u1**2 - u2**2) / (2 * g_prime)

    return {
