    # Conservation of energy for adiabatic flow (stagnation temperature):
    # Cp * T1 + 0.5 * v1^2 = Cp * T2 + 0.5 * v2^2
    # Temperature difference (Delta T) is the same in Kelvin and Celsius
    Cp = 1004.0  # physical constant (frozen, not an input)
    delta_T = (v1**2 - v2**2) / (2 * Cp)
    T2_C = T1_C + delta_T

    return {
