    # Calculate wind speed in the gap (M_d)
    M_d = M_s * (D_s / D_d)

    # Bernoulli's equation: P_s + 0.5 * rho * M_s^2 = P_d + 0.5 * rho * M_d^2
    # Pressure drop in the gap compared to non-gap flow: delta_P = P_d - P_s
    delta_P_Pa = 0.5 * rho * (M_s**2 - M_d**2)  # Pressure drop in Pascals (Pa)

    # Convert pressure drop from Pa to kPa
    delta_P_kPa = delta_P_Pa / 1000.0

    return {
        "1": {"value": round(delta_P_kPa, 1), "unit": "kPa"}
    }

