def solve(z1=1.0, M1=2.0, z2=10.0, M2=5.0) -> dict:
    # Logarithmic wind profile: M(z) = (u* / kappa) * ln(z / z0)
    # Taking the ratio: M2 / M1 = ln(z2 / z0) / ln(z1 / z0)
    # M2 * (ln(z1) - ln(z0)) = M1 * (ln(z2) - ln(z0))
    # (M1 - M2) * ln(z0) = M1 * ln(z2) - M2 * ln(z1)

    ln_z0 = (M1 * math.log(z2) - M2 * math.log(z1)) / (M1 - M2)
