    # U_avg is the velocity at grid point (3, 2)
    U_avg = (U_35_2 + U_25_2) / 2.0

    # Temperature gradient dT/dx at grid point (3, 2)
    dT_dx = (T_4_2 - T_2_2) / (2.0 * dX)

    # Warming rate in °C/s (Advection = -U * dT/dx)
    warming_rate_s = -U_avg * dT_dx

