    mfp = 0.0651e-6                   # m, mean free path of air (~0.0651 um)

    diameters_um = [d1, d2, d3, d4]

    def cunningham(dp):
        # dp in meters
        Kn = 2.0 * mfp / dp
        return 1.0 + Kn * (1.257 + 0.40 * math.exp(-1.10 / Kn))

    velocities = []
    for d_um in diameters_um:
        dp = d_um * 1e-6  # m
        Cc = cunningham(dp)
        vt = (rho_p_SI * dp**2 * g * Cc) / (18.0 * mu)  # m/s
        velocities.append(vt)

    results = {}
    for i, vt in enumerate(velocities, start=1):
        results[str(i)] = {"value": vt, "unit": "m/s"}

    return results

