    sigma = 5.670374419e-8  # W m^-2 K^-4

    def compute(Tt_K, tau):
        troposphere_blackbody_flux = sigma * Tt_K**4
        surface_blackbody_flux = (F0 - (1.0 - tau) * troposphere_blackbody_flux) / tau
        Tg_K = (surface_blackbody_flux / sigma) ** 0.25
        greenhouse_effect = surface_blackbody_flux - F0
        return Tg_K, greenhouse_effect

    results = {}
    key = 1

    # Order fixed by the problem statement: the three surface temperatures
    # first, then the three greenhouse-effect values, then both groups again
    # for the second tropospheric temperature.
    for Tt_K in (Tt1, Tt2):
        pairs = [compute(Tt_K, tau) for tau in (tau1, tau2, tau3)]

        for Tg_K, _ in pairs:
            results[str(key)] = {"value": Tg_K, "unit": "K"}
            key += 1

        for _, greenhouse_effect in pairs:
            results[str(key)] = {"value": greenhouse_effect, "unit": "W m^-2"}
            key += 1

